const raw = $json.choices?.[0]?.message?.content ?? '';
const fence = String.fromCharCode(96).repeat(3);
const cleaned = String(raw).replaceAll(fence + 'json', '').replaceAll(fence, '').trim();
const start = cleaned.indexOf('{');
const end = cleaned.lastIndexOf('}');
if (start < 0 || end <= start) throw new Error('Birinci çözüm JSON döndürmedi');
const parsed = JSON.parse(cleaned.slice(start, end + 1));
if (!parsed.question || !Array.isArray(parsed.steps) || !parsed.answer || !parsed.topic) throw new Error('Birinci çözüm eksik alan içeriyor');
const confidence = Number(parsed.confidence);
const image = $("Görseli Base64'e Çevir").first().json;
return [{ json: { question: String(parsed.question), steps: parsed.steps.map(String), answer: String(parsed.answer), topic: String(parsed.topic), confidence: Number.isFinite(confidence) ? Math.max(0, Math.min(1, confidence)) : 0, mimeType: image.mimeType, base64: image.base64, rawOpenAi: raw } }];

const escapeHtml = (value) => String(value ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#39;');

const rawQuestion = $json.question || '';
const rawSteps = Array.isArray($json.steps) ? $json.steps : [];
const rawAnswer = $json.answer || '';
const rawTopic = $json.topic || '';
const verification = $json.verification || {};

const question = escapeHtml(rawQuestion);
const steps = rawSteps.map(escapeHtml);
const answer = escapeHtml(rawAnswer);
const topic = escapeHtml(rawTopic);
const stepsHtml = steps.map((step, index) => '<li><strong>Adım ' + (index + 1) + ':</strong> ' + step + '</li>').join('');

const html = '<!DOCTYPE html><html lang="tr"><head><meta charset="UTF-8"><style>' +
  'body{margin:0;padding:32px;background:#f3f4f6;font-family:Arial,sans-serif}' +
  '.card{width:900px;background:#fff;border-radius:24px;padding:36px;box-shadow:0 12px 40px rgba(0,0,0,.12);color:#111827}' +
  '.title{font-size:32px;font-weight:800;margin-bottom:16px}.topic{font-size:18px;color:#2563eb;margin-bottom:24px;font-weight:700}' +
  '.question{font-size:22px;line-height:1.5;margin-bottom:28px}ol{padding-left:24px;font-size:19px;line-height:1.6}li{margin-bottom:12px}' +
  '.verified{margin:0 0 20px;color:#166534;font-size:15px;font-weight:700}.answer{margin-top:32px;padding:20px;border-radius:16px;background:#dcfce7;font-size:26px;font-weight:800;color:#166534}' +
  '</style></head><body><div class="card"><div class="title">Soru Çözümü</div><div class="topic">' + topic +
  '</div><div class="verified">✓ Bağımsız AI doğrulamasından geçti</div><div class="question">' + question + '</div><ol>' + stepsHtml + '</ol><div class="answer">Cevap: ' + answer +
  '</div></div></body></html>';

return [{ json: { question: rawQuestion, steps: rawSteps, answer: rawAnswer, topic: rawTopic, verification, html } }];

