const primary = $("AI Yanıtını Ayrıştır").first().json;
const image = $("Görseli Base64'e Çevir").first().json;
const independent = { question: String(parsed.question), steps: parsed.steps.map(String), answer: String(parsed.answer), topic: String(parsed.topic), confidence: Number.isFinite(confidence) ? Math.max(0, Math.min(1, confidence)) : 0 };
const primarySummary = { question: primary.question, steps: primary.steps, answer: primary.answer, topic: primary.topic, confidence: primary.confidence };
const judgePrompt = 'Görseldeki soruyu kendin yeniden çöz. Aşağıdaki iki aday çözümü yalnızca kanıt olarak karşılaştır; çoğunluğa körü körüne uyma. Görsel net değilse, cevaplar uyuşmuyorsa veya sonucu matematiksel/mantıksal olarak doğrulayamıyorsan approved=false ve needsManualReview=true yap. Güven 0.92 altında ise onaylama. Birinci çözüm: ' + JSON.stringify(primarySummary) + ' İkinci çözüm: ' + JSON.stringify(independent);
const judgePromptJsonEscaped = JSON.stringify(judgePrompt).slice(1, -1);
return [{ json: { ...independent, independent, primary: primarySummary, judgePrompt, judgePromptJsonEscaped, mimeType: image.mimeType, base64: image.base64, rawIndependent: raw } }];

const raw = $json.choices?.[0]?.message?.content ?? '';
const fence = String.fromCharCode(96).repeat(3);
const cleaned = String(raw).replaceAll(fence + 'json', '').replaceAll(fence, '').trim();
const start = cleaned.indexOf('{'); const end = cleaned.lastIndexOf('}');
if (start < 0 || end <= start) throw new Error('Hakem geçerli JSON döndürmedi');
const parsed = JSON.parse(cleaned.slice(start, end + 1));
if (!parsed.question || !Array.isArray(parsed.steps) || !parsed.answer || !parsed.topic) throw new Error('Hakem sonucu eksik');
const confidence = Number(parsed.confidence);
const safeConfidence = Number.isFinite(confidence) ? Math.max(0, Math.min(1, confidence)) : 0;
const approved = parsed.approved === true && parsed.needsManualReview !== true && safeConfidence >= 0.92;
const verification = { approved, confidence: safeConfidence, primaryAnswer: String(parsed.primaryAnswer ?? ''), independentAnswer: String(parsed.independentAnswer ?? ''), finalAnswer: String(parsed.answer), rationale: String(parsed.rationale ?? '') };
return [{ json: { question: String(parsed.question), steps: parsed.steps.map(String), answer: String(parsed.answer), topic: String(parsed.topic), verificationApproved: approved, verification } }];
